CREATE PROCEDURE dbo.GetCourseMarks
 @CourseID int=10
AS
BEGIN
 SET NOCOUNT ON;
 SELECT StudentID,Mark FROM dbo.Enrolments
 WHERE CourseID=@CourseID ORDER BY StudentID;
END;

